/// <summary>
/// MPJ_5013_ExciseRegisterEntry
/// Service class to update Nat3040 report number on the Excise Register and generate the reports
/// </summary>
class METNat3040RegisterUpdateService extends SysOperationServiceBase
{
    METNat3040ReportNumber  Nat3040Number;
    DocuTypeId              NAT3040SharePointPathDocuTypeId;

}

Method.Source:
    /// <summary>
    /// MPJ_5013_ExciseRegister
    /// Checks if run in batch or not.
    /// </summary>
    /// <param name = "_contract"> METNat3040RegisterUpdateContract</param>
    public void processOperation(METNat3040RegisterUpdateContract _contract)
    {
        METExciseRegisterEntry  metExciseRegisterEntry;
        NumberSeq               num;
        NoYesId                 UpdateNat3040 = _contract.parmUpdateNat3040();

        Nat3040Number = _contract.parmNat3040Number();

        if(UpdateNat3040 ==  NoYes::Yes)
        {
            ttsbegin;
            num     = NumberSeq::newGetNum(VendParameters::numRefNat30Number());
            Nat3040Number = num.num();
            update_recordset metExciseRegisterEntry
                setting Nat3040ReportNumber =  Nat3040Number
                where metExciseRegisterEntry.CustomerExempt      == NoYes::No
                &&    metExciseRegisterEntry.Nat3040ReportNumber == '';

            num.used();
            ttscommit;
        }
        
        NAT3040SharePointPathDocuTypeId = VendParameters::find().METNAT3040DocuTypeId;

        this.nat30export();
        this.nat40export();
   
    }

    /// <summary>
    /// MPJ_5013_ExciseRegisterEntry
    /// based on the input parameters filter the records from METExciseRegister table and store in csv
    /// </summary>
    private void nat30export()
    {
        METExciseRegisterEntry  metExciseRegisterEntry;
        METTariffItemCode       metTariffItemCode;
        METInventTable          metInventTable;

        CommaStreamIo           io          = CommaStreamIo::constructForWrite();
       
        io.writeExp(["@MET:ItemNo", "@MET:TariffItemCode", "@MET:StatCode","@MET:TariffItemDescription", "@MET:LALSQuantity",
                     "@MET:CustomsValue","@MET:DutyOriginCountryCode","@MET:PreferenceScheme","@MET:PreferenceRule",
                     "@MET:LQuantity","@MET:InvoiceAlcohol"]);
        
        while select sum(LitresOfAlcoholCalculated),sum(Quantity) 
            from metExciseRegisterEntry
                group by ItemId,TariffItemCode,DutyOriginCountryCode,DutyRate,PreferenceRule,StatCode,PreferenceScheme
                order by ItemId
                where   (metExciseRegisterEntry.OriginType              ==    METOriginType::SalesOrder 
                ||      metExciseRegisterEntry.OriginType               ==    METOriginType::SalesOrderReturn)
                &&      metExciseRegisterEntry.Nat3040ReportNumber      ==    Nat3040Number
                &&      metExciseRegisterEntry.NAT3040                  ==    METNAT3040::NAT30
            join Description 
            from metTariffItemCode
                group by Description
                where metTariffItemCode.TariffItem == metExciseRegisterEntry.TariffItemCode
            join BottleSize 
            from metInventTable
                group by BottleSize
                where   metInventTable.ItemId  ==  metExciseRegisterEntry.ItemId
        {
            Description     TarrifItemcodeDescription   =   metTariffItemCode.Description;
            Qty             CustomsValue                =   metExciseRegisterEntry.DutyRate *  metExciseRegisterEntry.LitresOfAlcoholCalculated;
            Qty             LQuantity                   =   metExciseRegisterEntry.Quantity *  metInventTable.BottleSize * -1;
            Qty             InvoiceAlcohol;

            if(LQuantity != 0)
            {
                InvoiceAlcohol  =   (LQuantity *100)/metExciseRegisterEntry.LitresOfAlcoholCalculated;
            }

            // Write line
            io.writeExp([metExciseRegisterEntry.ItemId,metExciseRegisterEntry.TariffItemCode,metExciseRegisterEntry.StatCode,
                         TarrifItemcodeDescription, metExciseRegisterEntry.LitresOfAlcoholCalculated,CustomsValue,metExciseRegisterEntry.DutyOriginCountryCode,
                         metExciseRegisterEntry.PreferenceScheme,metExciseRegisterEntry.PreferenceRule,LQuantity,InvoiceAlcohol]);
        }

        // Set stream
        System.IO.Stream    stream      = io.getStream();
        Filename            fileName    = this.getFileName("@MET:NAT30ReportFileNamePrefix");
       
        METSharePointHelper::saveToSharepoint(stream, fileName, NAT3040SharePointPathDocuTypeId);
    }

    /// <summary>
    ///MPJ_5013_ExciseRegisterEntry
    /// based on the input parameters filter the records from METExciseRegister table and store in csv
    /// </summary>
    private void nat40export()
    {
        METExciseRegisterEntry  metExciseRegisterEntry;
        CommaStreamIo           io  = CommaStreamIo::constructForWrite();

        io.writeExp(["@MET:TariffItemCode", "@MET:LALSQuantity","@SYS7867","@MET:DutyRate","@MET:ExciseAmount"]);

        while select sum(LitresOfAlcoholCalculated) 
            from metExciseRegisterEntry
                group by TariffItemCode,DutyRate
                where (metExciseRegisterEntry.OriginType            == METOriginType::SalesOrder
                 || metExciseRegisterEntry.OriginType               == METOriginType::SalesOrderReturn)
                &&    metExciseRegisterEntry.Nat3040ReportNumber    == Nat3040Number
                &&    metExciseRegisterEntry.NAT3040                == METNAT3040::NAT40
        {
            Description Units           = "@MET:LitresOfAlcohol";
            Qty         ExciseAmount    = metExciseRegisterEntry.LitresOfAlcoholCalculated * metExciseRegisterEntry.DutyRate;

            io.writeExp([metExciseRegisterEntry.TariffItemCode,metExciseRegisterEntry.LitresOfAlcoholCalculated,
                        Units,metExciseRegisterEntry.DutyRate,ExciseAmount]);
        }

        // Set stream
        System.IO.Stream    stream      = io.getStream();
        Filename            fileName    = this.getFileName("@MET:NAT40ReportFileNamePrefix");

        METSharePointHelper::saveToSharepoint(stream, fileName, NAT3040SharePointPathDocuTypeId);
        
    }

/// <summary>
/// Generate FileName for NAT30 and NAT40 reports
/// </summary>
/// <param name = "_fileNamePrefix">prefix to be applied</param>
/// <returns>fileName with embedded extension type</returns>
private Filename getFileName(str _fileNamePrefix)
{
    String20 todayDateStr = date2Str(DateTimeUtil::getSystemDate(0),123, DateDay::Digits2,DateSeparator::None, DateMonth::Digits2,DateSeparator::None, DateYear::Digits4);
    return strFmt(_fileNamePrefix + '_'+ todayDateStr +'_'+ Nat3040Number + '.csv');
}
